-- Stage 2 of 2: the clean, conformed rows the marts consume.

-- Source systems replay batches, so the same business key can
-- arrive more than once. Keep the most recently ingested version.
with deduplicated as (
    select
        *,
        row_number() over (partition by reading_id order by ingested_at desc nulls last) as _row_rank
    from {{ ref('cln_fact_pump_meter_readings') }}
    where _dq_is_valid
)

select
    reading_id,
    reading_ts,
    date_key,
    pump_id,
    site_id,
    product_id,
    totaliser_litres,
    litres_since_last_reading,
    meter_drift_pct,
    calibration_due,
    source_system_code,
    ingested_at,
    _cleansed_at
from deduplicated
where _row_rank = 1
